from AlgorithmImports import *


class ExactStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_order_pending = False
        self.strategy_b_order_pending = False

    def OnData(self, data):
        bars = data.Bars

        has_spy = bars.ContainsKey(self.spy)
        has_aapl = bars.ContainsKey(self.aapl)
        has_ibm = bars.ContainsKey(self.ibm)
        has_bac = bars.ContainsKey(self.bac)
        has_aig = bars.ContainsKey(self.aig)

        spy_crosses_above = False
        spy_crosses_below = False

        if has_spy:
            spy_close = float(bars[self.spy].Close)

            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_spy_sma
                    )

                self.previous_spy_sma = current_spy_sma

            self.previous_spy_close = spy_close

        if has_aapl:
            aapl_close = float(bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if not (has_spy and has_aapl and has_ibm and has_bac and has_aig):
            return

        if self.spy_sma.IsReady:
            if (
                self.strategy_a_lot > 0
                and not self.strategy_a_order_pending
                and spy_crosses_below
            ):
                self._submit_strategy_a_order(
                    -self.strategy_a_lot,
                    "Strategy A sell"
                )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_order_pending
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self._submit_strategy_b_order(
                -self.strategy_b_lot,
                "Strategy B sell"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_order_pending
            and self.spy_sma.IsReady
            and spy_crosses_above
        ):
            spy_close = float(bars[self.spy].Close)
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(target_value / spy_close)

            if quantity > 0:
                self._submit_strategy_a_order(
                    quantity,
                    "Strategy A buy"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_order_pending
            and self.aapl_red_streak >= 3
        ):
            aapl_close = float(bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20000.0:
                quantity = int(20000.0 / aapl_close)

                if quantity > 0:
                    self._submit_strategy_b_order(
                        quantity,
                        "Strategy B buy"
                    )

    def _submit_strategy_a_order(self, quantity, tag):
        self.strategy_a_order_pending = True
        ticket = self.MarketOrder(self.spy, quantity, False, tag)

        if ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.strategy_a_order_pending = False

    def _submit_strategy_b_order(self, quantity, tag):
        self.strategy_b_order_pending = True
        ticket = self.MarketOrder(self.aapl, quantity, False, tag)

        if ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.strategy_b_order_pending = False

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            self.strategy_a_lot = max(
                0,
                self.strategy_a_lot + int(order_event.FillQuantity)
            )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_order_pending = False

        elif order_event.Symbol == self.aapl:
            self.strategy_b_lot = max(
                0,
                self.strategy_b_lot + int(order_event.FillQuantity)
            )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_order_pending = False

